    @Test
    fun `kotlin判定逐字对拍PC基准`() {
        for (v in vectors) {
            val body = hexBytes(v.first)
            assertEquals("帧体 ${v.first.take(24)}…", v.second, GachaRecognizer.looksLikeGacha(body))
        }
    }

    private fun hexBytes(hex: String): ByteArray =
        hex.chunked(2).map { ((it.toInt(16)) and 0xff).toByte() }.toByteArray()
}
